import { describe, expect, test } from "bun:test";
import { resolveAgentOptions } from "../services/platform-helpers.js";

// The worker env is provisioned from `mergedOptions.nixConfig` (deployment
// manager wraps the spawn in `nix-shell -p <packages>`). Skills declare their
// native deps in `skillsConfig.skills[].nixPackages`; `lobu apply` bakes the
// union into the agent's nixConfig, but skills enabled via the UI/catalog API
// only write skillsConfig — so their packages must be unioned at resolve time
// or they never reach provisioning.
describe("resolveAgentOptions nix union (agent nixConfig ∪ enabled skills)", () => {
  test("an enabled skill's nixPackages reach nixConfig even when the agent has none", async () => {
    const settingsStore = {
      getSettings: async () =>
        ({
          models: ["openai/gpt-5"],
          skillsConfig: {
            skills: [
              {
                repo: "lobu/skills",
                name: "video",
                enabled: true,
                nixPackages: ["ffmpeg"],
              },
            ],
          },
        }) as any,
    };

    const resolved = await resolveAgentOptions(
      "agent-1",
      {},
      settingsStore as any,
      "org-1",
    );

    expect(resolved.nixConfig?.packages).toEqual(["ffmpeg"]);
  });

  test("agent packages come first and the union is deduped", async () => {
    const settingsStore = {
      getSettings: async () =>
        ({
          models: ["openai/gpt-5"],
          nixConfig: { packages: ["ripgrep", "ffmpeg"] },
          skillsConfig: {
            skills: [
              {
                repo: "lobu/skills",
                name: "video",
                enabled: true,
                nixPackages: ["ffmpeg", "yt-dlp"],
              },
            ],
          },
        }) as any,
    };

    const resolved = await resolveAgentOptions(
      "agent-1",
      {},
      settingsStore as any,
      "org-1",
    );

    expect(resolved.nixConfig?.packages).toEqual(["ripgrep", "ffmpeg", "yt-dlp"]);
  });

  test("disabled skills contribute nothing", async () => {
    const settingsStore = {
      getSettings: async () =>
        ({
          models: ["openai/gpt-5"],
          nixConfig: { packages: ["ripgrep"] },
          skillsConfig: {
            skills: [
              {
                repo: "lobu/skills",
                name: "video",
                enabled: false,
                nixPackages: ["ffmpeg"],
              },
            ],
          },
        }) as any,
    };

    const resolved = await resolveAgentOptions(
      "agent-1",
      {},
      settingsStore as any,
      "org-1",
    );

    expect(resolved.nixConfig?.packages).toEqual(["ripgrep"]);
  });

  test("flakeUrl is preserved when skill packages are unioned in", async () => {
    const settingsStore = {
      getSettings: async () =>
        ({
          models: ["openai/gpt-5"],
          nixConfig: { flakeUrl: "github:org/flake" },
          skillsConfig: {
            skills: [
              {
                repo: "lobu/skills",
                name: "video",
                enabled: true,
                nixPackages: ["ffmpeg"],
              },
            ],
          },
        }) as any,
    };

    const resolved = await resolveAgentOptions(
      "agent-1",
      {},
      settingsStore as any,
      "org-1",
    );

    expect(resolved.nixConfig?.flakeUrl).toBe("github:org/flake");
    expect(resolved.nixConfig?.packages).toEqual(["ffmpeg"]);
  });

  test("no nix anywhere leaves nixConfig unset (absent stays absent)", async () => {
    const settingsStore = {
      getSettings: async () =>
        ({
          models: ["openai/gpt-5"],
          skillsConfig: {
            skills: [
              {
                repo: "lobu/skills",
                name: "prose-only",
                enabled: true,
              },
            ],
          },
        }) as any,
    };

    const resolved = await resolveAgentOptions(
      "agent-1",
      {},
      settingsStore as any,
      "org-1",
    );

    expect(resolved.nixConfig).toBeUndefined();
  });
});

