import {
  createLogger,
  type MessagePayload,
  type NixConfig,
  type SkillsConfig,
} from "@lobu/core";

const logger = createLogger("platform-helpers");

/**
 * Effective nix config for a spawn: the agent's own `nixConfig` unioned with
 * the `nixPackages` declared by its ENABLED skills, agent packages first,
 * deduped. `lobu apply` bakes this union into the agent's nixConfig, but
 * skills enabled via the UI/catalog API only write `skillsConfig` — without
 * the resolve-time union their declared native deps never reach provisioning
 * (the nix-shell spawn wrap and the nix-cache domain grants both key off
 * `nixConfig`). Returns the input nixConfig untouched (possibly undefined)
 * when no skill contributes a package, so absent stays absent.
 */
export function resolveEffectiveNixConfig(settings: {
  nixConfig?: NixConfig;
  skillsConfig?: SkillsConfig;
}): NixConfig | undefined {
  const skillPackages = (settings.skillsConfig?.skills ?? [])
    .filter((skill) => skill.enabled)
    .flatMap((skill) => skill.nixPackages ?? []);
  if (skillPackages.length === 0) {
    return settings.nixConfig;
  }
  const packages = [
    ...new Set([...(settings.nixConfig?.packages ?? []), ...skillPackages]),
  ];
  return { ...settings.nixConfig, packages };
}

const effectiveNixConfig = resolveEffectiveNixConfig(settings);
if (effectiveNixConfig) {
  mergedOptions.nixConfig = effectiveNixConfig;
}

